sys_script_include.script:
var ScheduleUtils = Class.create();
ScheduleUtils.prototype = Object.extendsObject(AbstractAjaxProcessor, {

  validateSchedule: function() {
    var user = gs.getUserID();
    var now = new GlideDateTime();
    var validSchedules = [];

    var training = this.getParameter('sysparm_training');

    var sch = new GlideRecord('x_1805892_compan_0_schedule');
    if (training)
      sch.addQuery('training', training);
    sch.addQuery('schedule_for', '>', now);
    sch.query();

    while (sch.next()) {
      var scheduleId = sch.getUniqueValue();
      var instructor = sch.getValue('instructor');
      var capacity = parseInt(sch.getValue('max_participants'), 10);
      var trainingDate = new GlideDateTime(sch.getValue('schedule_for'));

      if (user == instructor)
        continue;

      var limitDate = new GlideDateTime();
      limitDate.addDays(1);
      if (trainingDate <= limitDate)
        continue;


      var current = new GlideRecord('x_1805892_compan_0_enrollment');
      current.addQuery('schedule', scheduleId);
      current.addQuery('state', 'IN', '1'); 
      current.query();
      if (current.getRowCount() >= capacity)
        continue;

      var existing = new GlideRecord('x_1805892_compan_0_enrollment');
      existing.addQuery('schedule', scheduleId);
      existing.addQuery('requested_for', user);
      existing.query();
      if (existing.next())
        continue;

      var past = new GlideRecord('x_1805892_compan_0_enrollment');
      past.addQuery('training', sch.getValue('training'));
      past.addQuery('requested_for', user);
      past.query();
      var count = 0;
      while (past.next()) count++;
      if (count >= 3)
        continue;

      validSchedules.push(scheduleId);
    }

    if (validSchedules.length === 0)
      return 'sys_id=none';

    return 'sys_idIN' + validSchedules.join(',');
  }
});
